def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1)) if len(labs) < 2 else np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    def ll(cols, want=False):
        Z = np.column_stack([S] + cols) if cols else S
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-8: break
        eta = np.clip(Z @ b, -30, 30)
        if want: return 1 / (1 + np.exp(-eta))
        return float(np.sum(y * eta - np.logaddexp(0, eta)))
    col = lambda js: [X[:, j] for j in js]
    chi = lambda a: stats.chi2.isf(a, 1)
    sel = []; base = ll([]); gates = [0.01 / p, 0.05 / p, 0.01 / p]
    while len(sel) < MAX_DRIVERS:
        cand = [j for j in range(p) if j not in sel and all(abs(R[j, k]) < 0.6 for k in sel)]
        if not cand: break
        lls = {j: ll(col(sel + [j])) for j in cand}
        j = max(lls, key=lls.get)
        if 2 * (lls[j] - base) < chi(gates[min(len(sel), 2)]): break
        clus = [k for k in cand if abs(R[j, k]) >= 0.6 and lls[k] >= lls[j] - 2]
        if len(clus) > 1:
            def gsum(c):
                l0 = ll(col(sel + [c]))
                return sum(ll(col(sel + [c, k])) - l0 for k in cand if k != c and abs(R[c, k]) >= 0.6)
            j = min(clus, key=gsum)
        sel.append(j); base = ll(col(sel))
    changed = True
    while changed and len(sel) > 1:
        changed = False; full = ll(col(sel))
        drops = {j: full - ll(col([k for k in sel if k != j])) for j in sel}
        j = min(drops, key=drops.get)
        if 2 * drops[j] < chi(0.05 / p): sel.remove(j); changed = True
    prods = []
    pairs = [(a, b) for a in range(p) for b in range(a, p)]
    full = ll(col(sel)); Z = np.column_stack([S] + col(sel)) if sel else S
    mu = np.clip(ll(col(sel), True), 1e-3, 1 - 1e-3)
    r = y - mu
    sc = []
    for a, b in pairs:
        v = X[:, a] * X[:, b]; v = v - Z @ np.linalg.lstsq(Z, v, rcond=None)[0]
        sc.append((v @ r) ** 2 / (np.sum(v * v * mu * (1 - mu)) + 1e-9))
    top = [pairs[i] for i in np.argsort(sc)[::-1][:15]]
    thr = chi(0.005 / len(pairs)); res = []
    for a, b in top:
        mains = sorted(set(sel) | {a, b})
        l0 = ll(col(mains)); l1 = ll(col(mains) + [X[:, a] * X[:, b]])
        if 2 * (l1 - l0) > thr: res.append((l1 - l0, a, b))
    used = set()
    for g, a, b in sorted(res, reverse=True):
        if a in used or b in used or len(prods) >= 2: continue
        prods.append((a, b)); used |= {a, b}
    for a, b in prods:
        for k in (a, b):
            if k not in sel and len(sel) < MAX_DRIVERS: sel.append(k)
    cols = tuple(ids[j] for j in sel)
    return Design(drivers=cols[:MAX_DRIVERS], columns=cols, products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

